export const MathUtils = {
  clamp: (v, lo, hi) => Math.min(hi, Math.max(lo, v)),
};

export class CatmullRomCurve3 {
  constructor(points, closed = false) { this.points = points; this.closed = closed; }
  getPoint(t) {
    const p = this.points, n = p.length;
    const seg = Math.min(Math.floor(t * n), n - 1);
    const lt = t * n - seg;
    const i1 = seg % n, i0 = (i1 - 1 + n) % n, i2 = (i1 + 1) % n, i3 = (i1 + 2) % n;
    const [p0, p1, p2, p3] = [p[i0], p[i1], p[i2], p[i3]];
    const u = lt, u2 = u * u, u3 = u2 * u;
    const cr = (a, b, c, d) => 0.5 * ((2 * b) + (-a + c) * u + (2 * a - 5 * b + 4 * c - d) * u2 + (-a + 3 * b - 3 * c + d) * u3);
    return new Vector3(cr(p0.x, p1.x, p2.x, p3.x), cr(p0.y, p1.y, p2.y, p3.y), cr(p0.z, p1.z, p2.z, p3.z));
  }
  getSpacedPoints(divisions) {
    const fine = [];
    const M = divisions * 8;
    for (let i = 0; i <= M; i++) fine.push(this.getPoint(i / M % 1));
    const cum = [0];
    for (let i = 1; i < fine.length; i++) cum.push(cum[i - 1] + fine[i].distanceTo(fine[i - 1]));
    const total = cum[cum.length - 1];
    const out = [];
    for (let d = 0; d <= divisions; d++) {
      const target = total * d / divisions;
      let lo = 0, hi = cum.length - 1;
      while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= target) lo = mid; else hi = mid; }
      const span = cum[hi] - cum[lo] || 1;
      const f = (target - cum[lo]) / span;
      out.push(fine[lo].clone().lerp(fine[hi], f));
    }
    return out;
  }
}
